 53	 */
 54	export function matchHostname(url: URL, hostname?: string, allowWildcard = false): boolean {
 55		if (!hostname) {
 56			return true;
 57		} else if (!allowWildcard || !hostname.startsWith('*')) {
 58			return hostname === url.hostname;
 59		} else if (hostname.startsWith('**.')) {
 60			const slicedHostname = hostname.slice(2); // ** length
 61			return slicedHostname !== url.hostname && url.hostname.endsWith(slicedHostname);
 62		} else if (hostname.startsWith('*.')) {
 63			const slicedHostname = hostname.slice(1); // * length
 64			// Check if url hostname ends with the base domain
 65			if (!url.hostname.endsWith(slicedHostname)) {
 66				return false;
 67			}
 68			// Extract the subdomain part (before the base domain, excluding the dot)
 69			const subdomainWithDot = url.hostname.slice(0, -(slicedHostname.length - 1));
 70			// Should be exactly one subdomain part followed by a dot
 71			return subdomainWithDot.endsWith('.') && !subdomainWithDot.slice(0, -1).includes('.');
 72		}
 73	
 74		return false;
 75	}
