133	
134		// Non-http(s) protocols are never allowed
135		if (!['http:', 'https:', 'data:'].includes(url.protocol)) {
136			return false;
137		}
138	
139		return (
140			domains.some((domain) => matchHostname(url, domain)) ||
141			remotePatterns.some((remotePattern) => matchPattern(url, remotePattern))
